test('project defaults apply only to future tasks and survive rename, archive and restart', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-default-'));
  const databasePath = join(directory, 'workboard.sqlite');
  let server;
  try {
    server = await start(databasePath);
    const request = (path, method, body) => fetch(`${server.url}/api/projects${path}`, method ? {
      method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    } : undefined);
    const first = await (await request('', 'POST', { name: 'First' })).json();
    const other = await (await request('', 'POST', { name: 'Other' })).json();
    assert.equal(first.defaultTaskPriority, 'Normal');
    assert.equal(other.defaultTaskPriority, 'Normal');
    const path = `/${first.id}`;
    const createTask = async (title) => (await request(`${path}/tasks`, 'POST', { title })).json();
    const original = await createTask('Original');
    await request(`${path}/tasks/${original.id}`, 'PATCH', { completed: true });
    const patchDefault = (defaultTaskPriority) => request(path, 'PATCH', { defaultTaskPriority });
    for (const value of ['', 'high', ' High ', null, 42]) {
      assert.equal((await patchDefault(value)).status, 400);
    }
    const tasks = [{ ...original, completed: true }];
    for (const priority of ['Low', 'Normal', 'High']) {
      const response = await patchDefault(priority);
      assert.equal(response.status, 200);
      assert.equal((await response.json()).defaultTaskPriority, priority);
      assert.deepEqual(await (await request(`${path}/tasks`)).json(), tasks);
      const task = await createTask(priority);
      assert.equal(task.priority, priority);
      tasks.push(task);
    }
    assert.deepEqual(await (await request(`/${other.id}`)).json(), other);
    await request(path, 'PATCH', { name: 'Renamed' });
    const summary = await (await request(path)).json();
    assert.equal(summary.defaultTaskPriority, 'High');
    assert.equal(summary.completedCount, 1);
    assert.equal(summary.totalCount, 4);
    await request(path, 'PATCH', { archived: true });
    assert.equal((await patchDefault('Low')).status, 409);
    await server.stop();
    server = await start(databasePath);
    assert.deepEqual(await (await request(path)).json(), { ...summary, archived: true });
    assert.deepEqual(await (await request(`${path}/tasks`)).json(), tasks);
    await request(path, 'PATCH', { archived: false });
    assert.deepEqual(await (await request(path)).json(), summary);
    const inherited = await createTask('After restore');
    assert.equal(inherited.priority, 'High');
    await patchDefault('Low');
    await server.stop();
    server = await start(databasePath);
    assert.equal((await (await request(path)).json()).defaultTaskPriority, 'Low');
    assert.deepEqual(await (await request(`${path}/tasks`)).json(), [...tasks, inherited]);
    assert.equal((await createTask('After restart')).priority, 'Low');
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const databasePath = process.env.DB_PATH || 'data/workboard.sqlite';
if (databasePath !== ':memory:') mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  PRAGMA foreign_keys = ON;
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  );
  CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id);
`);
// Existing databases predate archive support; migrate without changing IDs or tasks.
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
// Preserve existing task data while assigning the default priority.
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
// Project defaults apply only to future tasks, never to existing task priorities.
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'defaultTaskPriority')) {
  database.exec("ALTER TABLE projects ADD COLUMN defaultTaskPriority TEXT NOT NULL DEFAULT 'Normal' CHECK (defaultTaskPriority IN ('Low', 'Normal', 'High'))");
}
const projectQuery = `SELECT p.id, p.name, p.archived, p.defaultTaskPriority,
  COUNT(t.id) AS totalCount, COALESCE(SUM(t.completed), 0) AS completedCount
  FROM projects p LEFT JOIN tasks t ON t.project_id = p.id`;
const listProjects = database.prepare(`${projectQuery} GROUP BY p.id ORDER BY p.id`);
const getProject = database.prepare(`${projectQuery} WHERE p.id = ? GROUP BY p.id`);
const setProjectArchived = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const insertProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = database.prepare('SELECT id, title, completed, priority FROM tasks WHERE project_id = ? ORDER BY id');
const getTask = database.prepare('SELECT id, title, completed, priority FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = database.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)');
const setDefaultTaskPriority = database.prepare('UPDATE projects SET defaultTaskPriority = ? WHERE id = ?');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const setTaskPriority = database.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');

function projectJson(project) {
  return { ...project, archived: Boolean(project.archived) };
}

function taskJson(task) {
  return { ...task, completed: Boolean(task.completed) };
}

const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function json(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 64 * 1024) {
      const error = new Error('Request body is too large');
      error.status = 413;
      throw error;
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    const error = new Error('Invalid JSON');
    error.status = 400;
    throw error;
  }
}

const server = createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && path === '/health') return json(response, 200, { status: 'ok' });
    if (path === '/api/projects') {
      if (request.method === 'GET') return json(response, 200, listProjects.all().map(projectJson));
      if (request.method === 'POST') {
        const input = await readJson(request);
        const name = typeof input?.name === 'string' ? input.name.trim() : '';
        if (!name) return json(response, 400, { error: 'Project name is required' });
        const result = insertProject.run(name);
        return json(response, 201, projectJson(getProject.get(Number(result.lastInsertRowid))));
      }
    }
    const taskMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (taskMatch) {
      const projectId = Number(taskMatch[1]);
      const taskId = taskMatch[2] ? Number(taskMatch[2]) : null;
      const project = getProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (project.archived && ['POST', 'PATCH'].includes(request.method)) {
        return json(response, 409, { error: 'Archived project cannot be changed' });
      }
      if (request.method === 'GET' && taskId === null) {
        return json(response, 200, listTasks.all(projectId).map(taskJson));
      }
      if (request.method === 'POST' && taskId === null) {
        const input = await readJson(request);
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        const result = insertTask.run(projectId, title, getProject.get(projectId).defaultTaskPriority);
        return json(response, 201, taskJson(getTask.get(projectId, Number(result.lastInsertRowid))));
      }
      if (request.method === 'PATCH' && taskId !== null) {
        if (!getTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
        const input = await readJson(request);
        if (input && Object.hasOwn(input, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
        } else if (input && Object.hasOwn(input, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          setTaskPriority.run(input.priority, projectId, taskId);
        } else {
          if (typeof input?.completed !== 'boolean') {
            return json(response, 400, { error: 'Completed must be a boolean' });
          }
          updateTask.run(Number(input.completed), projectId, taskId);
        }
        return json(response, 200, taskJson(getTask.get(projectId, taskId)));
      }
    }
    const projectMatch = path.match(/^\/api\/projects\/(\d+)$/);
    if (projectMatch) {
      const projectId = Number(projectMatch[1]);
      const project = getProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (request.method === 'GET') return json(response, 200, projectJson(project));
      if (request.method === 'PATCH') {
        const input = await readJson(request);
        if (input && Object.hasOwn(input, 'name')) {
          if (project.archived) {
            return json(response, 409, { error: 'Archived project cannot be changed' });
          }
          const name = typeof input.name === 'string' ? input.name.trim() : '';
          if (!name) return json(response, 400, { error: 'Project name is required' });
          renameProject.run(name, projectId);
        } else if (input && Object.hasOwn(input, 'defaultTaskPriority')) {
          if (project.archived) {
            return json(response, 409, { error: 'Archived project cannot be changed' });
          }
          if (!['Low', 'Normal', 'High'].includes(input.defaultTaskPriority)) {
            return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          setDefaultTaskPriority.run(input.defaultTaskPriority, projectId);
        } else {
          if (typeof input?.archived !== 'boolean') {
            return json(response, 400, { error: 'Archived must be a boolean' });
          }
          setProjectArchived.run(Number(input.archived), projectId);
        }
        return json(response, 200, projectJson(getProject.get(projectId)));
      }
    }
    const asset = assets.get(/^\/projects\/\d+$/.test(path) ? '/' : path);
    if (request.method === 'GET' && asset) {
      response.writeHead(200, { 'Content-Type': asset[0] });
      return response.end(asset[1]);
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (!error.status) console.error(error);
    json(response, error.status || 500, { error: error.status ? error.message : 'Internal server error' });
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => {
    database.close();
    process.exit(0);
  }));
}

const app = document.querySelector('#app');

async function api(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to complete request');
  return data;
}

function element(tag, text) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  return node;
}

function showAlert(message) {
  let alert = app.querySelector('[role="alert"]');
  if (!alert) {
    alert = element('p');
    alert.setAttribute('role', 'alert');
    app.append(alert);
  }
  alert.textContent = message;
}

function projectRow(project, onArchiveChange) {
  const row = element('li');
  row.dataset.testid = 'project-row';
  row.append(element('span', project.name));
  const open = element('button', 'Open project');
  open.type = 'button';
  open.addEventListener('click', () => location.assign(`/projects/${project.id}`));
  const summary = element('span', `${project.completedCount}/${project.totalCount} completed`);
  summary.dataset.testid = 'project-summary';
  const archive = element('button', project.archived ? 'Restore project' : 'Archive project');
  archive.type = 'button';
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    app.querySelector('[role="alert"]')?.remove();
    try {
      const saved = await api(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, saved);
      onArchiveChange();
    } catch (error) {
      showAlert(error.message);
    } finally {
      archive.disabled = false;
    }
  });
  row.append(summary, open, archive);
  return row;
}

async function showProjects() {
  app.replaceChildren(element('h1', 'Workboard'));
  const form = element('form');
  const label = element('label', 'Project name');
  label.htmlFor = 'project-name';
  const input = element('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  const create = element('button', 'Create project');
  create.type = 'submit';
  form.append(label, input, create);
  const list = element('ul');
  list.className = 'projects';
  let projects = [];
  const filterLabel = element('label', 'Project filter');
  filterLabel.htmlFor = 'project-filter';
  const filter = element('select');
  filter.id = 'project-filter';
  for (const value of ['Active', 'Archived']) {
    const option = element('option', value);
    option.value = value;
    filter.append(option);
  }
  const filters = element('div');
  filters.className = 'project-filter';
  filters.append(filterLabel, filter);
  function renderProjects() {
    list.replaceChildren(...projects
      .filter((project) => Boolean(project.archived) === (filter.value === 'Archived'))
      .map((project) => projectRow(project, renderProjects)));
  }
  filter.addEventListener('change', renderProjects);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (create.disabled) return;
    app.querySelector('[role="alert"]')?.remove();
    const name = input.value.trim();
    if (!name) {
      showAlert('Project name is required');
      input.focus();
      return;
    }
    create.disabled = true;
    try {
      const project = await api('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      projects.push(project);
      renderProjects();
      input.value = '';
      input.focus();
    } catch (error) {
      showAlert(error.message);
    } finally {
      create.disabled = false;
    }
  });
  app.append(form, filters, list);
  // Enable creation only after the initial list has loaded, preserving ordering.
  create.disabled = true;
  try {
    projects = await api('/api/projects');
    renderProjects();
    create.disabled = false;
  } catch (error) {
    showAlert(error.message);
  }
}

async function showTasks(project) {
  const projectId = project.id;
  const archived = Boolean(project.archived);
  const endpoint = `/api/projects/${projectId}/tasks`;
  let tasks = [];
  const saving = new Set();
  const form = element('form');
  const titleLabel = element('label', 'Task title');
  titleLabel.htmlFor = 'task-title';
  const input = element('input');
  input.id = 'task-title';
  input.name = 'title';
  input.type = 'text';
  const create = element('button', 'Create task');
  create.type = 'submit';
  create.disabled = true;
  form.append(titleLabel, input, create);

  const filterLabel = element('label', 'Task filter');
  filterLabel.htmlFor = 'task-filter';
  const filter = element('select');
  filter.id = 'task-filter';
  for (const value of ['All', 'Open', 'Completed']) {
    const option = element('option', value);
    option.value = value;
    filter.append(option);
  }
  const filters = element('div');
  filters.className = 'task-filter';
  const priorityFilterLabel = element('label', 'Priority filter');
  priorityFilterLabel.htmlFor = 'priority-filter';
  const priorityFilter = element('select');
  priorityFilter.id = 'priority-filter';
  for (const value of ['All', 'Low', 'Normal', 'High']) {
    const option = element('option', value);
    option.value = value;
    priorityFilter.append(option);
  }
  filters.append(filterLabel, filter, priorityFilterLabel, priorityFilter);
  const list = element('ul');
  list.className = 'tasks';

  function renderTasks() {
    const visible = tasks.filter((task) =>
      (filter.value === 'All'
        || (filter.value === 'Completed' ? task.completed : !task.completed))
      && (priorityFilter.value === 'All' || task.priority === priorityFilter.value));
    list.replaceChildren(...visible.map((task) => {
      const row = element('li');
      row.dataset.testid = 'task-row';
      const checkbox = element('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.disabled = archived || saving.has(task.id);
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      async function saveTask(changes) {
        saving.add(task.id);
        checkbox.disabled = true;
        renameInput.disabled = true;
        renameButton.disabled = true;
        priority.disabled = true;
        app.querySelector('[role="alert"]')?.remove();
        try {
          const saved = await api(`${endpoint}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(changes),
          });
          Object.assign(task, saved);
        } catch (error) {
          checkbox.checked = task.completed;
          showAlert(error.message);
        } finally {
          saving.delete(task.id);
          renderTasks();
        }
      }
      checkbox.addEventListener('change', () => saveTask({ completed: checkbox.checked }));
      const renameForm = element('form');
      const renameLabel = element('label', 'New task title');
      renameLabel.htmlFor = `new-task-title-${task.id}`;
      const renameInput = element('input');
      renameInput.id = renameLabel.htmlFor;
      renameInput.name = 'title';
      renameInput.type = 'text';
      renameInput.disabled = archived || saving.has(task.id);
      const renameButton = element('button', 'Rename task');
      renameButton.type = 'submit';
      renameButton.disabled = archived || saving.has(task.id);
      renameForm.append(renameLabel, renameInput, renameButton);
      renameForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (archived || saving.has(task.id)) return;
        app.querySelector('[role="alert"]')?.remove();
        const title = renameInput.value.trim();
        if (!title) {
          showAlert('Task title is required');
          renameInput.focus();
          return;
        }
        await saveTask({ title });
      });
      const priorityLabel = element('label', 'Task priority');
      priorityLabel.htmlFor = `task-priority-${task.id}`;
      const priority = element('select');
      priority.id = priorityLabel.htmlFor;
      for (const value of ['Low', 'Normal', 'High']) {
        const option = element('option', value);
        option.value = value;
        priority.append(option);
      }
      priority.value = task.priority;
      priority.disabled = archived || saving.has(task.id);
      priority.addEventListener('change', () => {
        if (archived || saving.has(task.id)) return;
        return saveTask({ priority: priority.value });
      });
      row.append(checkbox, element('span', task.title), renameForm, priorityLabel, priority);
      return row;
    }));
  }

  filter.addEventListener('change', renderTasks);
  priorityFilter.addEventListener('change', renderTasks);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (create.disabled) return;
    app.querySelector('[role="alert"]')?.remove();
    const title = input.value.trim();
    if (!title) {
      showAlert('Task title is required');
      input.focus();
      return;
    }
    create.disabled = true;
    try {
      const task = await api(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      });
      tasks.push(task);
      renderTasks();
      input.value = '';
      input.focus();
    } catch (error) {
      showAlert(error.message);
    } finally {
      create.disabled = archived;
    }
  });
  app.append(form, filters, defaultPriorityControl(project), list);
  tasks = await api(endpoint);
  renderTasks();
  create.disabled = archived;
}

function defaultPriorityControl(project) {
  const control = element('div');
  const label = element('label', 'Default task priority');
  label.htmlFor = 'default-task-priority';
  const select = element('select');
  select.id = label.htmlFor;
  for (const value of ['Low', 'Normal', 'High']) {
    const option = element('option', value);
    option.value = value;
    select.append(option);
  }
  select.value = project.defaultTaskPriority;
  select.disabled = project.archived;
  select.addEventListener('change', async () => {
    if (select.disabled) return;
    select.disabled = true;
    app.querySelector('[role="alert"]')?.remove();
    try {
      const saved = await api(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ defaultTaskPriority: select.value }),
      });
      Object.assign(project, saved);
    } catch (error) {
      showAlert(error.message);
    } finally {
      select.value = project.defaultTaskPriority;
      select.disabled = project.archived;
    }
  });
  control.append(label, select);
  return control;
}

function showRenameForm(project, heading) {
  const form = element('form');
  const label = element('label', 'New project name');
  label.htmlFor = 'new-project-name';
  const input = element('input');
  input.id = 'new-project-name';
  input.name = 'name';
  input.type = 'text';
  input.disabled = project.archived;
  const rename = element('button', 'Rename project');
  rename.type = 'submit';
  rename.disabled = project.archived;
  form.append(label, input, rename);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (rename.disabled) return;
    app.querySelector('[role="alert"]')?.remove();
    const name = input.value.trim();
    if (!name) {
      showAlert('Project name is required');
      input.focus();
      return;
    }
    rename.disabled = true;
    try {
      const saved = await api(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      Object.assign(project, saved);
      heading.textContent = project.name;
      document.title = `${project.name} — Workboard`;
      input.value = '';
      input.focus();
    } catch (error) {
      showAlert(error.message);
    } finally {
      rename.disabled = project.archived;
    }
  });
  app.append(form);
}

async function showProject(id) {
  app.replaceChildren();
  const back = element('button', 'Projects');
  back.type = 'button';
  back.addEventListener('click', () => location.assign('/'));
  app.append(back);
  try {
    const project = await api(`/api/projects/${id}`);
    document.title = `${project.name} — Workboard`;
    const heading = element('h1', project.name);
    app.prepend(heading);
    if (project.archived) app.append(element('p', 'Archived project'));
    showRenameForm(project, heading);
    await showTasks(project);
  } catch (error) {
    if (!app.querySelector('h1')) app.prepend(element('h1', 'Workboard'));
    showAlert(error.message);
  }
}

const match = location.pathname.match(/^\/projects\/(\d+)$/);
(match ? showProject(match[1]) : showProjects()).finally(() => {
  app.setAttribute('aria-busy', 'false');
});

{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import { DatabaseSync } from 'node:sqlite';

async function start(databasePath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: databasePath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let output = '';
  const port = await new Promise((resolve, reject) => {
    child.stdout.on('data', (chunk) => {
      output += chunk;
      const match = output.match(/listening on port (\d+)/);
      if (match) resolve(match[1]);
    });
    child.once('error', reject);
    child.once('exit', (code) => reject(new Error(`Server exited: ${code}`)));
  });
  return {
    url: `http://127.0.0.1:${port}`,
    async stop() {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

test('legacy project databases migrate without losing IDs or tasks', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-migration-'));
  const databasePath = join(directory, 'legacy.sqlite');
  let server;
  try {
    const legacy = new DatabaseSync(databasePath);
    legacy.exec(`
      CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
      CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT,
        project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL,
        completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)));
      INSERT INTO projects (id, name) VALUES (17, 'Legacy');
      INSERT INTO tasks (id, project_id, title, completed) VALUES (23, 17, 'Saved task', 1);
    `);
    legacy.close();
    server = await start(databasePath);
    const expected = [{ id: 17, name: 'Legacy', archived: false, defaultTaskPriority: 'Normal', totalCount: 1, completedCount: 1 }];
    assert.deepEqual(await (await fetch(`${server.url}/api/projects`)).json(), expected);
    assert.deepEqual(await (await fetch(`${server.url}/api/projects/17/tasks`)).json(), [
      { id: 23, title: 'Saved task', completed: true, priority: 'Normal' },
    ]);
    await server.stop();
    server = await start(databasePath);
    assert.deepEqual(await (await fetch(`${server.url}/api/projects`)).json(), expected);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('health, project validation, creation order, routes, and restart persistence', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  let server;
  try {
    const databasePath = join(directory, 'nested', 'projects.sqlite');
    server = await start(databasePath);
    const request = (path, options) => fetch(`${server.url}${path}`, options);
    const create = (name) => request('/api/projects', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
    });
    const health = await request('/health');
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    for (const name of ['', '  \t\n', null, 42]) {
      const invalid = await create(name);
      assert.equal(invalid.status, 400);
      assert.match((await invalid.json()).error, /Project name is required/);
    }
    assert.deepEqual(await (await request('/api/projects')).json(), []);
    const malformed = await request('/api/projects', { method: 'POST', body: '{' });
    assert.equal(malformed.status, 400);
    const firstResponse = await create('  First project  ');
    assert.equal(firstResponse.status, 201);
    const first = await firstResponse.json();
    assert.equal(first.name, 'First project');
    const second = await (await create('<script>Not HTML</script>')).json();
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await (await request('/api/projects')).json(), [first, second]);
    assert.deepEqual(await (await request(`/api/projects/${first.id}`)).json(), first);
    for (const path of ['/', `/projects/${first.id}`]) {
      const page = await request(path);
      assert.equal(page.status, 200);
      assert.match(await page.text(), /<title>Workboard<\/title>/);
    }
    assert.equal((await request('/api/projects/999999')).status, 404);

    const tasksPath = `/api/projects/${first.id}/tasks`;
    const otherTasksPath = `/api/projects/${second.id}/tasks`;
    const createTask = (title, path = tasksPath) => request(path, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
    });
    const completeTask = (id, completed, path = tasksPath) => request(`${path}/${id}`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed }),
    });
    for (const title of ['', ' \t\n ', null, 42]) {
      const invalid = await createTask(title);
      assert.equal(invalid.status, 400);
      assert.match((await invalid.json()).error, /Task title is required/);
    }
    assert.deepEqual(await (await request(tasksPath)).json(), []);
    const taskResponse = await createTask('  First task  ');
    assert.equal(taskResponse.status, 201);
    const task = await taskResponse.json();
    assert.equal(task.title, 'First task');
    assert.equal(task.completed, false);
    const nextTask = await (await createTask('<script>Task text</script>')).json();
    assert.deepEqual(await (await request(tasksPath)).json(), [task, nextTask]);
    assert.deepEqual(await (await request(otherTasksPath)).json(), []);
    const otherTask = await (await createTask('Other project task', otherTasksPath)).json();
    assert.equal((await completeTask(task.id, true, otherTasksPath)).status, 404);
    assert.equal((await completeTask(task.id, 'true')).status, 400);
    assert.equal((await completeTask(task.id, null)).status, 400);
    assert.equal((await createTask('Missing', '/api/projects/999999/tasks')).status, 404);
    assert.equal((await request('/api/projects/999999/tasks')).status, 404);
    const completedResponse = await completeTask(task.id, true);
    assert.equal(completedResponse.status, 200);
    assert.deepEqual(await completedResponse.json(), { ...task, completed: true });
    assert.deepEqual(await (await completeTask(task.id, false)).json(), task);
    await completeTask(task.id, true);
    assert.deepEqual(await (await request(otherTasksPath)).json(), [otherTask]);
    await server.stop();
    server = await start(databasePath);
    let firstSummary = { ...first, totalCount: 2, completedCount: 1 };
    const secondSummary = { ...second, totalCount: 1, completedCount: 0 };
    assert.deepEqual(await (await request('/api/projects')).json(), [firstSummary, secondSummary]);
    assert.deepEqual(await (await request(`/api/projects/${first.id}`)).json(), firstSummary);
    assert.deepEqual(await (await request(tasksPath)).json(), [{ ...task, completed: true }, nextTask]);
    assert.deepEqual(await (await request(otherTasksPath)).json(), [otherTask]);
    assert.deepEqual(await (await completeTask(task.id, false)).json(), task);
    assert.equal((await request(`/projects/${first.id}`)).status, 200);
    await completeTask(task.id, true);
    const rename = (name) => request(`/api/projects/${first.id}`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
    });
    for (const name of ['', ' \t\n ', null, 42]) {
      const invalid = await rename(name);
      assert.equal(invalid.status, 400);
      assert.match((await invalid.json()).error, /Project name is required/);
      assert.deepEqual(await (await request(`/api/projects/${first.id}`)).json(), firstSummary);
    }
    const renamed = await rename('  Renamed project  ');
    assert.equal(renamed.status, 200);
    firstSummary = { ...firstSummary, name: 'Renamed project' };
    assert.deepEqual(await renamed.json(), firstSummary);
    assert.deepEqual(await (await request('/api/projects')).json(), [firstSummary, secondSummary]);
    assert.deepEqual(await (await request(tasksPath)).json(), [{ ...task, completed: true }, nextTask]);
    await server.stop();
    server = await start(databasePath);
    assert.deepEqual(await (await request('/api/projects')).json(), [firstSummary, secondSummary]);
    assert.equal((await request(`/projects/${first.id}`)).status, 200);
    const archiveProject = (archived) => request(`/api/projects/${first.id}`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archived }),
    });
    assert.equal((await archiveProject('true')).status, 400);
    assert.deepEqual(await (await archiveProject(true)).json(), { ...firstSummary, archived: true });
    assert.equal((await rename('Forbidden rename')).status, 409);
    assert.deepEqual(await (await request(`/api/projects/${first.id}`)).json(), {
      ...firstSummary, archived: true,
    });
    assert.equal((await createTask('Forbidden')).status, 409);
    assert.equal((await completeTask(task.id, false)).status, 409);
    assert.deepEqual(await (await request(tasksPath)).json(), [{ ...task, completed: true }, nextTask]);
    await server.stop();
    server = await start(databasePath);
    assert.deepEqual(await (await request('/api/projects')).json(), [
      { ...firstSummary, archived: true }, secondSummary,
    ]);
    assert.deepEqual(await (await archiveProject(false)).json(), firstSummary);
    firstSummary = { ...firstSummary, name: 'Restored and renamed' };
    assert.deepEqual(await (await rename(' Restored and renamed ')).json(), firstSummary);
    assert.deepEqual(await (await request(tasksPath)).json(), [{ ...task, completed: true }, nextTask]);
    assert.equal((await completeTask(task.id, false)).status, 200);
    await server.stop();
    server = await start(databasePath);
    assert.deepEqual(await (await request(`/api/projects/${first.id}`)).json(), {
      ...firstSummary, completedCount: 0,
    });
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});


test('task renaming preserves ownership, order, completion, summaries and restart data', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-task-rename-'));
  const databasePath = join(directory, 'workboard.sqlite');
  let server;
  try {
    server = await start(databasePath);
    const request = async (path, method, body) => fetch(`${server.url}/api/projects${path}`, method ? {
      method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    } : undefined);
    const first = await (await request('', 'POST', { name: 'First' })).json();
    const second = await (await request('', 'POST', { name: 'Second' })).json();
    const tasksPath = `/${first.id}/tasks`;
    const task = await (await request(tasksPath, 'POST', { title: 'Original' })).json();
    const next = await (await request(tasksPath, 'POST', { title: 'Next' })).json();
    await request(`${tasksPath}/${task.id}`, 'PATCH', { completed: true });
    const rename = (title, path = tasksPath) => request(`${path}/${task.id}`, 'PATCH', { title });
    const summary = await (await request(`/${first.id}`)).json();
    for (const title of ['', ' \t\n ', null, 42]) {
      const invalid = await rename(title);
      assert.equal(invalid.status, 400);
      assert.equal((await invalid.json()).error, 'Task title is required');
    }
    assert.equal((await rename('Wrong owner', `/${second.id}/tasks`)).status, 404);
    const renamed = { ...task, title: 'Renamed task', completed: true };
    const response = await rename('  Renamed task  ');
    assert.equal(response.status, 200);
    assert.deepEqual(await response.json(), renamed);
    assert.deepEqual(await (await request(tasksPath)).json(), [renamed, next]);
    assert.deepEqual(await (await request(`/${second.id}/tasks`)).json(), []);
    assert.deepEqual(await (await request(`/${first.id}`)).json(), summary);
    await request(`/${first.id}`, 'PATCH', { archived: true });
    assert.equal((await rename('Forbidden')).status, 409);
    await server.stop();
    server = await start(databasePath);
    assert.deepEqual(await (await request(tasksPath)).json(), [renamed, next]);
    assert.deepEqual(await (await request(`/${first.id}`)).json(), { ...summary, archived: true });
    await request(`/${first.id}`, 'PATCH', { archived: false });
    assert.deepEqual(await (await rename(' Restored title ')).json(), { ...renamed, title: 'Restored title' });
    await server.stop();
    server = await start(databasePath);
    assert.deepEqual(await (await request(tasksPath)).json(), [{ ...renamed, title: 'Restored title' }, next]);
    assert.deepEqual(await (await request(`/${first.id}`)).json(), summary);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});


